import polars as pl

df = pl.DataFrame(
    {
        "date": ["2026-01-01", "2026-01-01", "2026-01-02", "2026-01-02"],
        "city": ["London", "Paris", "London", "Paris"],
        "temperature": [5.0, 7.0, 6.0, 8.0],
    }
)

wide_df = df.pivot(on="city", index="date", values="temperature")

print(wide_df)
